function reviewCue(x){const p=phrases.find(v=>v.lang===x.lang&&v.text===x.text),scene=courses[x.lang]?.scenes?.find(v=>v[4]===x.text),meaning=x.meaning||p?.meaning||phraseMeta(x.text,x.lang).meaning||"",context=x.context||p?.context||scene?.[0]||"",prompt=plainExpression(x.prompt||p?.prompt||scene?.[2]||"");return {meaning,context,prompt,promptAudio:!!scene?.[2]&&prompt===scene[2]}}
function reviewHintText(text,level=1){const words=String(text||"").trim().split(/\s+/);if(!words.length)return "";if(level===1)return words.map((w,i)=>i===0?w:(w.length<=2?w:w.slice(0,1)+"_".repeat(Math.min(6,w.length-1)))).join(" ");return words.map(w=>w.length<=4?w:w.slice(0,Math.ceil(w.length*.55))+"…").join(" ")}
function renderPhraseHome(tab="due"){const due=dueReviews(),badge=$("dueBadge"),session=$("reviewSession"),browser=$("phraseBrowser"),weakCount=reviews.filter(x=>(x.lapses||0)>0).length;if($("phraseStats"))$("phraseStats").innerHTML=`<button data-stat-tab="due"><b>${due.length}</b><small>오늘</small></button><button data-stat-tab="weak"><b>${weakCount}</b><small>어려움</small></button><button data-stat-tab="saved"><b>${phrases.length}</b><small>전체</small></button>`;document.querySelectorAll("[data-stat-tab]").forEach(b=>b.onclick=()=>{const t=b.dataset.statTab;document.querySelectorAll(".phraseTabs button").forEach(x=>x.classList.toggle("active",x.dataset.phraseTab===t));renderPhraseHome(t)});if(!session)return;badge.textContent=due.length+"개 복습";if(tab==="saved"){session.classList.add("hidden");browser.classList.remove("hidden");renderPhraseLibrary();return}browser.classList.add("hidden");session.classList.remove("hidden");const items=phrasePool(tab),x=items[0];if(!x){session.innerHTML='<div class="reviewDone"><span>✓</span><b>'+(tab==="due"?"오늘 연습 완료":"지금 어려운 문장이 없어요")+'</b></div>';return}const idx=tab==="due"?due.length:items.length,cue=reviewCue(x),front=cue.prompt||cue.context||"이 상황에서 어떻게 대답할까요?",mastery=x.mastery||0,hint1=reviewHintText(x.text,1),hint2=reviewHintText(x.text,2);session.innerHTML='<div class="reviewProgress"><span>'+(courses[x.lang]?.flag||"•")+' '+(courses[x.lang]?.name||"")+'</span><b>'+idx+'개 남음</b></div><div class="reviewFlash recallFlash"><small>'+(tab==="weak"?"어려운 문장":"오늘 복습")+'</small>'+(cue.context?'<span class="reviewContext">'+cue.context+'</span>':'')+'<h3>'+front+'</h3>'+(cue.meaning?'<button id="reviewMeaningBtn" class="meaningToggle">뜻 보기</button><p id="reviewMeaningText" class="reviewMeaning hidden">'+cue.meaning+'</p>':'')+'<div id="reviewHintBox" class="reviewHintBox"><small>힌트 · '+(mastery>=2?"가볍게":"단어부터")+'</small><b>'+(mastery>=2?hint2:hint1)+'</b></div><div class="reviewPractice"><button id="cardMic" class="primary">🎙 말하기</button><button id="reviewMoreHint" class="ghost">힌트 더</button><button id="reviewRevealBtn" class="ghost">정답 보기</button></div><div id="reviewAnswer" class="reviewAnswer hidden"><small>정답</small><b>'+x.text+'</b>'+(cue.meaning?'<p>'+cue.meaning+'</p>':'')+'<div class="reviewPractice"><button id="cardSpeak" class="ghost mini">🔊 듣기</button><button id="reviewRepeat" class="primary mini">🎙 다시 말하기</button></div></div><div id="cardTranscript" class="transcript"></div></div><div id="reviewGradeBar" class="reviewGradeBar hidden"><button data-grade="again">몰랐음<small>10분</small></button><button data-grade="hard">힌트로 성공<small>가까이</small></button><button data-grade="good" class="good">바로 말함<small>간격 늘리기</small></button></div>';let hintStage=mastery>=2?2:1,revealed=false;const listen=()=>speakText(x.text,x.lang);if($("reviewMeaningBtn"))$("reviewMeaningBtn").onclick=()=>{$("reviewMeaningText").classList.toggle("hidden");$("reviewMeaningBtn").textContent=$("reviewMeaningText").classList.contains("hidden")?"뜻 보기":"뜻 닫기"};const recognize=()=>{const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(!SR)return;const r=new SR();r.lang=courses[x.lang].voice;$("cardTranscript").textContent="듣는 중…";r.onresult=e=>{const heard=e.results[0][0].transcript,score=similarity(heard,x.text);$("cardTranscript").innerHTML='“'+heard+'”<br><b>'+score+'%</b>';$("reviewAnswer").classList.remove("hidden");$("reviewGradeBar").classList.remove("hidden")};r.start()};$("cardMic").onclick=recognize;$("reviewMoreHint").onclick=()=>{hintStage++;$("reviewHintBox").querySelector("b").textContent=hintStage===2?hint2:x.text;$("reviewMoreHint").textContent=hintStage>=3?"힌트 전체":"힌트 더";if(hintStage>=3)$("reviewMoreHint").disabled=true};$("reviewRevealBtn").onclick=()=>{revealed=true;$("reviewAnswer").classList.remove("hidden");$("reviewRevealBtn").classList.add("hidden");$("reviewGradeBar").classList.remove("hidden")};$("cardSpeak").onclick=listen;$("reviewRepeat").onclick=recognize;document.querySelectorAll(".reviewGradeBar button").forEach(b=>b.onclick=()=>{let grade=b.dataset.grade;if(revealed&&grade==="good")grade="again";else if(hintStage>1&&grade==="good")grade="hard";gradeReview(x,grade);renderPhraseHome(tab)})}
function renderWeakness(){const count=$("weakCount"),box=$("weaknessList");if(!count||!box)return;const list=[...reviews].sort((a,b)=>(b.lapses||0)-(a.lapses||0));count.textContent=list.length;box.innerHTML=list.length?list.slice(0,6).map(x=>`<div class="weakRow"><span>${courses[x.lang]?.flag||"•"}</span><div><b>${x.text}</b><small>실수 ${x.lapses||1}회 · 최근 점수 ${x.lastScore??"-"}%</small></div><strong>${Math.max(1,100-(x.lapses||1)*15)}%</strong></div>`).join(""):`<div class="emptyState">학습을 시작하면 자주 막히는 표현이 여기에 쌓여요.</div>`}
function dueReviews(){return reviews.filter(x=>Number(x.due||0)<=Date.now()).sort((a,b)=>(b.lapses||0)-(a.lapses||0)||(Number(a.due||0)-Number(b.due||0)))}
function phrasePool(tab="due"){
  if(tab==="due")return dueReviews();
  if(tab==="weak")return [...reviews].filter(x=>(x.lapses||0)>0).sort((a,b)=>(b.lapses||0)-(a.lapses||0)||(Number(a.due||0)-Number(b.due||0)));
  return [];
}
function gradeReview(x,grade){if(grade==="again"){x.lapses=(x.lapses||0)+1;x.interval=1;x.due=Date.now()+600000;x.mastery=Math.max(0,(x.mastery||0)-1)}else if(grade==="hard"){x.interval=Math.max(1,Math.round((x.interval||1)*1.5));x.due=Date.now()+x.interval*86400000;x.mastery=Math.max(0,x.mastery||0)}else{x.mastery=(x.mastery||0)+1;x.interval=x.mastery>=3?Math.max(7,Math.round((x.interval||1)*2.5)):Math.max(1,Math.round((x.interval||1)*1.8));x.due=Date.now()+x.interval*86400000;done++}save();render()}
