async function saveCaptured(withPractice=false){const t=$("capturedText").value.trim();if(!t)return;let meaning="";try{const data=await requestAIData("meaning",t);meaning=data.korean||data.target||""}catch(err){console.error(err)}rememberPhrase(t,"heard",{context:"콘텐츠에서 저장",meaning});const x=phrases.find(p=>p.lang===lang&&p.text===t);if(withPractice&&x)queuePhrase(x);$("aiInput").value=t;$("captureReview").classList.add("hidden");renderPhraseLibrary();if(withPractice)document.querySelector(".phraseHome")?.scrollIntoView({behavior:"smooth"})}
