const escapeMarkup=value=>String(value??"").replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]));
function boldMarkup(value){return escapeMarkup(value).replace(/\*\*(.+?)\*\*/gs,"<strong>$1</strong>")}
function plainExpression(value){return String(value??"").replace(/\*\*/g,"").replace(/^\s*[-•]\s*/,"").trim()}
function learningPair(text,meaning=""){let target=plainExpression(text),korean=plainExpression(meaning);const marker=target.indexOf("::");if(marker>=0){korean=korean||plainExpression(target.slice(marker+2));target=target.slice(0,marker).trim()}const match=target.match(/[가-힣ㄱ-ㅎㅏ-ㅣ]/);if(match){korean=korean||plainExpression(target.slice(match.index));target=target.slice(0,match.index).replace(/[\s(:：\-–—|]+$/g,"").trim()}return {text:target,meaning:korean}}
function cleanExpressionData(data){const first=learningPair(data.target,data.korean);return {...data,target:first.text,korean:first.meaning,pronunciation:plainExpression(data.pronunciation),note:plainExpression(data.note),usage:Object.fromEntries(Object.entries(data.usage||{}).map(([key,value])=>[key,plainExpression(value)])),examples:(Array.isArray(data.examples)?data.examples:[]).map(x=>learningPair(x.text,x.meaning)).filter(x=>x.text&&x.meaning),related:(Array.isArray(data.related)?data.related:[]).map(x=>learningPair(x.text,x.meaning)).filter(x=>x.text)}}
function repairExpressionData(persist=true){let changed=false;const oldTexts=new Map();for(const item of phrases){if(item.source!=="expression"&&item.source!=="expression-example")continue;const original=item.text,pair=learningPair(item.text,item.meaning);if(pair.text&&pair.text!==item.text){item.text=pair.text;oldTexts.set(item.lang+"\u0000"+original,pair);changed=true}if(pair.meaning&&pair.meaning!==item.meaning){item.meaning=pair.meaning;changed=true}for(const key of ["note","prompt"]){if(item[key]?.includes("**")){item[key]=plainExpression(item[key]);changed=true}}if(Array.isArray(item.examples)){const clean=item.examples.map(x=>learningPair(x.text,x.meaning));if(JSON.stringify(clean)!==JSON.stringify(item.examples)){item.examples=clean;changed=true}}}for(const review of reviews){const old=oldTexts.get(review.lang+"\u0000"+review.text);const pair=old||((review.source==="expression"||review.source==="expression-example")?learningPair(review.text,review.meaning):null);if(pair){if(pair.text&&pair.text!==review.text){review.text=pair.text;changed=true}if(pair.meaning&&pair.meaning!==review.meaning){review.meaning=pair.meaning;changed=true}}if(review.source==="expression"&&review.prompt?.includes("**")){review.prompt=plainExpression(review.prompt);changed=true}}if(changed){if(persist)save();else{localStorage.phrases=JSON.stringify(phrases);localStorage.reviews=JSON.stringify(reviews)}}return changed}
let expressionDraft=null;
function expressionItems(){const key=$("phraseLang")?.value||"all",q=($("phraseSearch")?.value||"").toLocaleLowerCase();return phrases.filter(x=>(key==="all"||x.lang===key)&&(!q||x.text.toLocaleLowerCase().includes(q)||(x.meaning||"").toLocaleLowerCase().includes(q)||(x.context||"").toLocaleLowerCase().includes(q))).slice(0,100)}
function usageEntries(usage){if(Array.isArray(usage))return usage.map((value,index)=>["쓰임 "+(index+1),value]);const labels={register:"격식",region:"지역",channel:"말·글",frequency:"빈도",situation:"주로 쓰는 상황"};return Object.entries(usage||{}).filter(([key,value])=>labels[key]&&value).map(([key,value])=>[labels[key],value])}
function decoratePhraseMetadata(){const cards=document.querySelectorAll(".phraseCard"),items=expressionItems();cards.forEach((card,i)=>{const x=items[i],detail=card.querySelector(".phraseDetail");if(!x||!detail||detail.querySelector(".phraseRichMeta")||(!x.usage&&!x.examples&&!x.note))return;const usage=usageEntries(x.usage),examples=Array.isArray(x.examples)?x.examples:[];const rich=document.createElement("div");rich.className="phraseRichMeta";rich.innerHTML='<b class="phraseDetailTitle">한국어 설명</b>'+(usage.length?'<dl class="phraseUsage">'+usage.map(([label,value])=>'<div><dt>'+escapeMarkup(label)+'</dt><dd>'+escapeMarkup(value)+'</dd></div>').join("")+'</dl>':'')+(x.note?'<p>'+escapeMarkup(x.note)+'</p>':'')+(examples.length?'<div class="phraseExamples"><b>연결된 예문</b>'+examples.map(example=>'<p><b>'+escapeMarkup(example.text)+'</b><br>'+escapeMarkup(example.meaning)+'</p>').join("")+'</div>':'');detail.prepend(rich)})}
function renderExpressionResult(data){const box=$("expressionResult");if(!box)return;const usage=usageEntries(data.usage),examples=Array.isArray(data.examples)?data.examples:[],related=Array.isArray(data.related)?data.related:[];box.innerHTML='<div class="expressionResultHead"><div><h3>'+escapeMarkup(data.target)+'</h3><small class="expressionDetectedLang">'+escapeMarkup((courses[data.language]?.flag||"")+" "+(courses[data.language]?.name||""))+'</small><span class="expressionPronunciation">'+escapeMarkup(data.pronunciation||"")+'</span></div><button id="expressionListen" class="ghost mini">🔊 듣기</button></div><p class="expressionMeaning">'+escapeMarkup(data.korean||"")+'</p><dl class="usageGrid">'+usage.map(([label,value])=>'<div><dt>'+escapeMarkup(label)+'</dt><dd>'+escapeMarkup(value)+'</dd></div>').join("")+'</dl>'+(data.note?'<div class="expressionNote"><b>뉘앙스와 주의점</b><p>'+escapeMarkup(data.note)+'</p></div>':'')+'<div class="expressionExamples"><h4>실제 예문</h4>'+examples.map((example,i)=>'<div class="expressionExample"><div><b>'+escapeMarkup(example.text)+'</b><small>'+escapeMarkup(example.meaning)+'</small></div><button class="ghost mini expressionExampleSave" data-example="'+i+'">이 문장 저장</button></div>').join("")+'</div>'+(related.length?'<p class="expressionRelated"><b>비슷한 표현</b> · '+related.map(item=>escapeMarkup(item.text)+' — '+escapeMarkup(item.meaning)).join(' · ')+'</p>':'')+'<div class="expressionActions"><button id="expressionSaveReview" class="primary">표현·예문 저장 + 복습</button><button id="expressionMore" class="ghost">새 예문 3개 더</button></div>';box.classList.remove("hidden");$("expressionListen").onclick=()=>speakText(data.target,data.language);$("expressionSaveReview").onclick=()=>saveExpressionAnalysis();$("expressionMore").onclick=()=>analyzeExpression(true);document.querySelectorAll(".expressionExampleSave").forEach(button=>button.onclick=()=>{saveExpressionExample(Number(button.dataset.example),true);button.textContent="✓ 외국어 문장 저장됨";button.disabled=true})}
async function analyzeExpression(more=false){const input=$("expressionInput"),button=$("expressionAnalyze"),box=$("expressionResult"),selectedLang=more&&expressionDraft?.language?expressionDraft.language:$("expressionLang").value,text=more&&expressionDraft?.target?expressionDraft.target:input.value.trim();if(!text)return;if(!syncReady()){alert("표현 분석을 사용하려면 먼저 동기화를 설정해주세요.");openSync();return}button.disabled=true;button.textContent="분석 중…";box.classList.remove("hidden");box.innerHTML='<div class="expressionLoading">뜻과 실제 쓰임을 확인하고 있어요…</div>';try{const c=syncConfig(),known=more&&expressionDraft?.examples?.length?" 이미 만든 예문: "+expressionDraft.examples.map(x=>x.text).join(" / ")+". 이 예문과 겹치지 않게 새 예문을 만들어줘.":"",context=($("expressionContext").value.trim()||"사용자가 영상이나 일상에서 발견한 표현")+known,r=await fetch(c.url+"/functions/v1/ai-coach",{method:"POST",headers:{apikey:c.key,Authorization:"Bearer "+c.key,"Content-Type":"application/json","x-sync-token":c.token},body:JSON.stringify({mode:"expression",lang:selectedLang,text,context})}),raw=await r.json(),data=cleanExpressionData(raw);if(!r.ok)throw new Error(data.error||"표현 분석 실패");data.language=courses[data.language]?data.language:selectedLang;if(!data.target||!data.examples.length)throw new Error("학습 문장을 분리하지 못했어요. 다시 분석해주세요.");$("expressionLang").value=data.language;localStorage.expressionLang=data.language;data.sourceContext=$("expressionContext").value.trim();if(more&&expressionDraft){data.examples=[...expressionDraft.examples,...data.examples].filter((item,index,array)=>array.findIndex(x=>x.text===item.text)===index);data.usage=expressionDraft.usage;data.note=expressionDraft.note;data.korean=expressionDraft.korean;data.pronunciation=expressionDraft.pronunciation;data.related=expressionDraft.related}expressionDraft=data;renderExpressionResult(data)}catch(error){box.innerHTML='<div class="expressionLoading expressionError">분석하지 못했어요. 잠시 후 다시 시도해주세요.<br><small>'+escapeMarkup(error?.message||error)+'</small></div>'}finally{button.disabled=false;button.textContent="분석"}}
function expressionPracticePrompt(data,meaning){const situation=data.usage?.situation||data.sourceContext||"실제 대화";return situation+"\n‘"+meaning+"’라고 어떻게 말할까요?"}
function queueExpressionReview(data,text,meaning,context,prompt){let review=reviews.find(x=>x.lang===data.language&&x.text===text);const meta={meaning,context,prompt,source:"expression",due:Date.now()};if(review)Object.assign(review,meta);else reviews.push({lang:data.language,text,interval:1,lapses:0,lastScore:100,...meta})}
function addExpressionExample(data,example,queue=false){const context=(data.usage?.situation||data.target+" 예문").slice(0,120),prompt=expressionPracticePrompt(data,example.meaning);let phrase=phrases.find(x=>x.lang===data.language&&x.text===example.text);const meta={meaning:example.meaning,context,prompt,source:"expression-example",usage:data.usage,note:data.note,createdAt:Date.now()};if(phrase)Object.assign(phrase,meta);else phrases.unshift({lang:data.language,text:example.text,...meta});if(queue)queueExpressionReview(data,example.text,example.meaning,context,prompt)}
function saveExpressionExample(index,queue=false){const data=expressionDraft,example=data?.examples?.[index];if(!data||!example)return;addExpressionExample(data,example,queue);save();renderPhraseLibrary();if(queue)renderPhraseHome("due")}
function saveExpressionAnalysis(){const data=expressionDraft;if(!data)return;const context=data.sourceContext||data.usage?.situation||"새 표현",prompt=expressionPracticePrompt(data,data.korean);let phrase=phrases.find(x=>x.lang===data.language&&x.text===data.target);const meta={meaning:data.korean,context,prompt,source:"expression",pronunciation:data.pronunciation,usage:data.usage,note:data.note,examples:data.examples,related:data.related,createdAt:Date.now()};if(phrase)Object.assign(phrase,meta);else{phrase={lang:data.language,text:data.target,...meta};phrases.unshift(phrase)}queueExpressionReview(data,data.target,data.korean,context,prompt);data.examples.forEach(example=>addExpressionExample(data,example,true));save();renderPhraseLibrary();renderPhraseHome("due");$("expressionSaveReview").textContent="✓ 외국어 문장만 복습에 추가됨";$("expressionSaveReview").disabled=true}
function setupExpressionCollector(){const select=$("expressionLang");select.innerHTML=Object.entries(courses).map(([key,course])=>'<option value="'+key+'">'+course.flag+' '+course.name+'</option>').join("");select.value=localStorage.expressionLang||lang;select.onchange=()=>localStorage.expressionLang=select.value;$("expressionToggle").onclick=()=>{$("expressionForm").classList.toggle("hidden");$("expressionToggle").textContent=$("expressionForm").classList.contains("hidden")?"＋ 추가":"닫기";if(!$("expressionForm").classList.contains("hidden"))$("expressionInput").focus()};$("expressionAnalyze").onclick=()=>analyzeExpression(false);$("expressionInput").onkeydown=event=>{if(event.key==="Enter"){event.preventDefault();analyzeExpression(false)}};const list=$("phraseList");new MutationObserver(decoratePhraseMetadata).observe(list,{childList:true});decoratePhraseMetadata()}
repairExpressionData(false);
setupExpressionCollector();
